def holes(shape):
    grid=[[1 if x else 0 for x in row] for row in shape]
    H,W=len(grid),len(grid[0])
    # flood fill from edges over background (zeros) that are connected
    seen=[[False]*W for _ in range(H)]
    st=[(i,j) for i in range(H) for j in range(W) if grid[i][j]==0 and ((i==0 or i==H-1 or j==0 or j==W-1))]
    for i,j in st: seen[i][j]=True
    while st:
        a,b=st.pop()
        for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
            if 0<=x<H and 0<=y<W and not seen[x][y] and grid[x][y]==0:
                seen[x][y]=True; st.append((x,y))
    total_zeros=sum(1 for r in grid for c in r if c==0)
    outside=sum(1 for i in range(H) for j in range(W) if grid[i][j]==0 and seen[i][j])
    return total_zeros-outside
