def holes(g_):
    H=len(g_); W=len(g_[0])
    seen=[[False]*W for _ in range(H)]
    st=[(i,j) for i in range(H) for j in range(W) if g_[i][j]==0 and ((i in (0,H-1) or j in (0,W-1)))]
    for i,j in st: seen[i][j]=True
    while st:
        a,b=st.pop()
        for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
            if 0<=x<H and 0<=y<W and not seen[x][y] and g_[x][y]==0:
                seen[x][y]=True; st.append((x,y))
    return sum(1 for i in range(H) for j in range(W) if g_[i][j]==0 and not seen[i][j])
