def props(g_):
    H=len(g_);W=len(g_[0])
    def get(g,h,w):
        return tuple(tuple(r) for r in g)
    s=map(sum,g_)
    # point symmetry (180)
    ps=all(g_[i][j]==g_[H-1-i][W-1-j] for i in range(H) for j in range(W))
    # vertical flip
    vf=all(g_[i][j]==g_[H-1-i][j] for i in range(H) for j in range(W))
    # horizontal flip
    hf=all(g_[i][j]==g_[i][W-1-j] for i in range(H) for j in range(W))
    return dict(h=H,w=W,s=sum(map(sum,g_)),ps=ps,vf=vf,hf=hf)
