def comps(g,conn='q'):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    col=max(set(sum(g,[]))-{0})
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    if conn=='q': dirs+=((1,1),(1,-1),(-1,1),(-1,-1))
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=set()
                while st:
                    a,b=st.pop(); comp.add((a,b))
                    for da,db in dirs:
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==col and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,c0=min(rs),min(cs)
                h=max(rs)-r0+1; w=max(cs)-c0+1
                gr=[[1 if (r0+rr,c0+cc) in comp else 0 for cc in range(w)] for rr in range(h)]
                syms={'hv':all(gr[r][c]==gr[r][w-1-c] for r in range(h) for c in range(w)),
                      'vb':all(gr[r][c]==gr[h-1-r][c] for r in range(h) for c in range(w)),
                      'rot180':all(gr[r][c]==gr[h-1-r][w-1-c] for r in range(h) for c in range(w)),
                      'transpose':all(gr[r][c]==gr[c][r] for r in range(min(h,w)) for c in range(min(h,w)))}
                out.append({'sz':len(comp),'pos':(r0,c0),'dims':(h,w),'grid':gr,'nsym':sum(syms.values()),'conn':conn})
