    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    col=max(set(sum(g,[]))-{0})
    dirs=((1,0),(-1,0),(0,1),(0,-1))
    if diag: dirs+=((1,1),(1,-1),(-1,1),(-1,-1))
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=set()
                while st:
                    a,b=st.pop(); comp.add((a,b))
                    for da,db in dirs:
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==col and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                r0,c0=min(rs),min(cs)
                h=max(rs)-r0+1; w=max(cs)-c0+1
                gr=[[g[r0+rr][c0+cc] for cc in range(w)] for rr in range(h)]
                # holes: enclosed zeros via BFS within bbox
                holes=0
                for rr in range(1,h-1):
                    for cc in range(1,w-1):
                        if gr[rr][cc]==0:
                            q=[(rr,cc)]; seen_h=[[False]*w for _ in range(h)]; seen_h[rr][cc]=True; touch=False
                            while q:
                                u,v=q.pop()
                                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                                    x,y=u+da,v+db
                                    if 0<=x<h and 0<=y<w:
                                        if gr[x][y]==0 and not seen_h[x][y]:
                                            seen_h[x][y]=True; q.append((x,y))
                                        elif gr[x][y]==1: touch=True
                            if touch: holes+=1
                nsym=0
                if all(gr[r][c]==gr[r][w-1-c] for r in range(h) for c in range(w)): nsym+=1
                if all(gr[r][c]==gr[h-1-r][c] for r in range(h) for c in range(w)): nsym+=2
                if all(gr[r][c]==gr[h-1-r][w-1-c] for r in range(h) for c in range(w)): nsym+=3
                if h>=w and all(gr[r][c]==gr[c][r] for r in range(w) for c in range(w)): nsym+=4
                if h<=w and all(gr[r][c]==gr[c][r] for r in range(h) for c in range(h)): nsym+=5
                out.append({'sz':len(comp),'pos':(r0,c0),'dims':(h,w),'holes':holes,'nsym':nsym,'grid':gr,'diag':diag})
    return out
for key in ['Demo pair 1','Demo pair 2']:
    d=comps(G[key+' input'],diag=True); o=G[key+' output']
    print('===',key)
    for s in sorted(d,key=lambda t:-t['sz']):
        mark=' <-- MATCH' if s['grid']==[list(r) for r in o] else ''
        print(s['sz'],s['pos'],s['dims'],'holes',s['holes'],'nsym',s['nsym'],mark)

